using System;using System.Linq;using System.Collections.Generic;using System.Threading;using System.Threading.Tasks;using System.Web.Script.Serialization;using ReplierDesktop;
public static class ReferenceGroundingChecks {
 static void Check(bool b,string s){if(!b)throw new Exception(s);Console.WriteLine("PASS "+s);}
 public static int Main(){try{var json=new JavaScriptSerializer();string source="Lumen 차량의 분홍 색상과 하얀 시트가 예쁘네요.";
 Check(ReferenceGrounding.Observed("LUMEN으로",source),"verified name with case differences and Korean particles remains allowed");Check(!ReferenceGrounding.Observed("RTX5090","RTX4070 제품입니다"),"different product identity is not accepted because its family is related");
 var missing=ReferenceGrounding.Parse("{\"word_kinds\":[{\"id\":0,\"kind\":\"explicit_reference\",\"identity\":\"product\"}]}",new[]{"네뷸라"},source);Check(!missing.Supported&&missing.Reason.Contains("네뷸라"),"unseen named reference requires actual source presence rather than general topic approval");
 Check(ReferenceGrounding.Parse("{\"word_kinds\":[{\"id\":0,\"kind\":\"explicit_reference\",\"identity\":\"product\"}]}",new[]{"Lumen"},source).Supported,"same name is allowed when it actually occurs in the evidence");Check(ReferenceGrounding.Parse("{\"word_kinds\":[{\"id\":0,\"kind\":\"ordinary_expression\"}]}",new[]{"마음에드네요"},source).Supported,"subjective reaction does not require literal wording overlap");
 bool rejected=false;try{ReferenceGrounding.Parse("{\"word_kinds\":[]}",new[]{"네뷸라"},source);}catch(System.IO.InvalidDataException){rejected=true;}Check(rejected,"classification cannot omit unmatched words");
 using(var model=new LocalModel("unused")){int laterChecks=0;var guard=new WholeCommentGrounding(model,(body,t)=>{var req=SceneMaterial.Json(json.Serialize(body));var props=CaptionService.Get(CaptionService.Get(req,"format"),"properties");if(CaptionService.Get(props,"references")!=null)return Task.FromResult("{\"references\":[{\"name\":\"네뷸라\",\"identity\":\"product\"}]}");laterChecks++;return Task.FromResult("{\"supported\":true,\"source\":0}");});var result=guard.Assess(new Video{Title="차량 스킨 소개"},new[]{new KeyValuePair<string,CaptionCue>("c0",new CaptionCue{Text=source})},"네뷸라 차량 스킨 예쁘네요",CancellationToken.None).GetAwaiter().GetResult();Check(!result.Supported&&laterChecks==0,"broad model approval cannot override a program-detected ungrounded identity");}
 return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
